SELECT order_status, COUNT(*) AS orders, ROUND(SUM(p.payment_value),2) AS payments
FROM orders o JOIN order_payments p USING(order_id)
GROUP BY 1 ORDER BY payments DESC;

WITH x AS (
 SELECT c.customer_zip_code_prefix AS customer_zip, s.seller_zip_code_prefix AS seller_zip
 FROM orders o JOIN customers c ON o.customer_id=c.customer_id JOIN order_items oi ON o.order_id=oi.order_id JOIN sellers s ON oi.seller_id=s.seller_id
 WHERE o.order_id='a77e1550db865202c56b19ddc6dc4d53' AND oi.order_item_id=1
), g AS (
 SELECT x.*, (SELECT AVG(geolocation_lat) FROM geolocation WHERE geolocation_zip_code_prefix=x.customer_zip) AS clat, (SELECT AVG(geolocation_lng) FROM geolocation WHERE geolocation_zip_code_prefix=x.customer_zip) AS clng, (SELECT AVG(geolocation_lat) FROM geolocation WHERE geolocation_zip_code_prefix=x.seller_zip) AS slat, (SELECT AVG(geolocation_lng) FROM geolocation WHERE geolocation_zip_code_prefix=x.seller_zip) AS slng FROM x
) SELECT customer_zip, seller_zip, ROUND(6371 * ACOS(LEAST(1.0, GREATEST(-1.0, SIN(RADIANS(clat))*SIN(RADIANS(slat))+COS(RADIANS(clat))*COS(RADIANS(slat))*COS(RADIANS(clng-slng))))),0) AS straight_line_km FROM g;

SELECT COUNT(*) AS orders_with_payments_no_items
FROM (
  SELECT DISTINCT p.order_id
  FROM order_payments p
  WHERE NOT EXISTS (
    SELECT 1 FROM order_items i WHERE i.order_id = p.order_id
  )
) x;

SELECT COUNT(*) AS orders_with_items_no_payments
FROM (
  SELECT DISTINCT i.order_id
  FROM order_items i
  WHERE NOT EXISTS (
    SELECT 1 FROM order_payments p WHERE p.order_id = i.order_id
  )
) x;

WITH x AS (
 SELECT COALESCE(t.product_category_name_english,p.product_category_name,'unknown') category, oi.order_id, oi.order_item_id, o.order_status, o.order_purchase_timestamp, o.order_delivered_customer_date, o.order_estimated_delivery_date, r.review_score
 FROM order_items oi JOIN products p USING(product_id) LEFT JOIN product_category_translation t USING(product_category_name) JOIN orders o USING(order_id) LEFT JOIN order_reviews r USING(order_id)
), m AS (
 SELECT category, COUNT(*) items, ROUND(AVG(review_score),2) rating, ROUND(100.0*SUM(review_score<=2)/COUNT(review_score),1) low_review_pct, ROUND(100.0*SUM(order_status IN ('canceled','unavailable'))/COUNT(*),1) failed_pct, ROUND(AVG(CASE WHEN order_delivered_customer_date IS NOT NULL THEN DATE_DIFF('day',order_purchase_timestamp,order_delivered_customer_date) END),1) delivery_days, ROUND(100.0*SUM(order_delivered_customer_date>order_estimated_delivery_date)/SUM(order_delivered_customer_date IS NOT NULL),1) late_pct
 FROM x GROUP BY category
)
SELECT * FROM m WHERE items>=100 AND (rating < 3.9 OR late_pct >= 10 OR failed_pct >= 1) ORDER BY items DESC;
